<script setup>
import AppReviewNotice from './AppReviewNotice.vue';
import { computed, ref, reactive, watch, onMounted, nextTick } from 'vue';
import { USER_FACING_ERROR } from '../../../shared/userFacingError.js';
import AssetDefinitionView from './AssetDefinitionView.vue';
import AssetAppRun from './AssetAppRun.vue';
import AssetConnectionBindings from './AssetConnectionBindings.vue';
import SourceStepPicker from './SourceStepPicker.vue';
import { assetHandoffKey } from '../../app-workshop/handoff.js';
import { useAssetApps } from '../useAssetApps.js';
import { appStatus, blankDefinition, clone, fileAliases, inputDefaults, parseObject, parseRunInput, pretty, verificationCases, runLabels } from '../assetAppsModel.js';
import { accountDraftKey, clearDraftIfUnchanged, readDraft, writeDraft } from '../draftStore.js';

const props = defineProps({ ownerId: { type: String, required: true }, files: { type: Array, default: () => [] }, captureRunId: String, initialAppId: String, initialVersionId: String, unifiedAuthoring: Boolean, embedded: Boolean, poolDetail: Boolean });
const emit = defineEmits(['captured', 'capability-draft', 'legacy', 'community', 'connections', 'author', 'initial-opened', 'join', 'back']);
const work = useAssetApps(props.ownerId), { s } = work;
const query = ref(''), picker = ref(null), editor = ref(null), editorText = ref(''), instruction = ref(''), preview = ref(null), creatorWarnings = ref([]), importPreview = ref(null), importPackage = ref(null), selectedNodes = ref([]);
const handoff = computed(() => { const value = readDraft(assetHandoffKey(props.ownerId, s.selected?.id)); return value?.versionId === s.selected?.versionId ? value : null; });
const showRun = ref(false), showValidation = ref(false), values = reactive({}), fileBindings = reactive({});
const savedConfirmation = ref(null), savedSummary = ref(null), validationPanel = ref(null);
const sourceCapture = ref(null), sourceStepIds = ref([]), sourceRunId = ref(''), sourceBaseline = ref('');
const importBindings = ref({}), selectedBindings = ref({});
const blankCase = index => ({ label: index ? '不同输入用例' : '原任务用例', input: '{}', expectation: '{"mode":"fields","values":{}}', fileBindings: {} });
const caseEditor = (value, index) => value ? { label: value.label || blankCase(index).label, input: pretty(value.input || {}), expectation: pretty(value.expectation || { mode: 'fields', values: {} }), fileBindings: clone(value.fileBindings || {}) } : blankCase(index);
const cases = ref([blankCase(0), blankCase(1)]), includeAdditionalCase = ref(false);
const savedOriginalCase = computed(() => s.selected?.testCases?.[0] || null);
const originalNeedsCompletion = computed(() => !savedOriginalCase.value?.expectation || (savedOriginalCase.value.expectation.mode === 'fields' && !Object.keys(savedOriginalCase.value.expectation.values || {}).length) || (savedOriginalCase.value.expectation.mode === 'json_equals' && !Object.hasOwn(savedOriginalCase.value.expectation, 'value')));
function resetCaseEditors() {
  cases.value = [caseEditor(s.selected?.testCases?.[0], 0), caseEditor(s.selected?.testCases?.[1], 1)];
  includeAdditionalCase.value = false;
}
function restoreOriginalCase() { if (savedOriginalCase.value) cases.value[0] = caseEditor(savedOriginalCase.value, 0); }
function copyOriginalToAdditional() { if (savedOriginalCase.value) cases.value[1] = { ...caseEditor(savedOriginalCase.value, 1), label: '不同输入用例' }; }
const filtered = computed(() => s.items.filter(item => [item.name, item.description].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())));
const definition = computed(() => { try { return parseObject(editorText.value, '应用定义'); } catch { return null; } });
const aliases = computed(() => fileAliases(s.selected?.definition));
const currentFields = computed(() => s.selected?.definition?.inputSchema?.properties || {});
const versions = computed(() => (s.selected?.versions || [{ versionId: s.selected?.versionId }]).map(version => ({ ...version, versionId: version.versionId || version.id })));
const enabled = computed(() => s.selected?.enabledVersionId === s.selected?.versionId);
const previewCurrent = computed(() => preview.value && preview.value.submitted === editorText.value);
const draftKey = () => accountDraftKey(props.ownerId, 'asset-app-editor', editor.value?.appId || 'new');
const error = message => { s.error = message; };

watch(editorText, value => { preview.value = null; if (editor.value) writeDraft(draftKey(), { editor: clone(editor.value), text: value }); }, { flush: 'sync' });
watch([() => s.selected?.id, () => s.selected?.versionId], () => { showRun.value = false; showValidation.value = false; selectedNodes.value = []; selectedBindings.value = clone(s.selected?.runtimeBindings || {}); });
watch([() => props.ownerId, () => s.selected?.id, () => s.selected?.versionId], resetCaseEditors, { immediate: true });
function openEditor(value = blankDefinition(), base = null, restore = false) {
  savedConfirmation.value = null;
  const context = base ? { appId: base.id, revision: base.revision, baseVersionId: base.versionId } : {};
  const saved = restore && readDraft(accountDraftKey(props.ownerId, 'asset-app-editor', context.appId || 'new'));
  editor.value = saved?.editor || context; editorText.value = saved?.text || pretty(value);
  instruction.value = ''; preview.value = null; importPreview.value = null; importPackage.value = null;
  showRun.value = false; showValidation.value = false; s.error = '';
  if (saved) s.notice = '已恢复此账号上次未提交的编辑，请核对后预览保存。';
}
function closeEditor() { if (!s.busy) { editor.value = null; preview.value = null; s.notice = '未提交修改已在此账号本地保留，可从编辑入口恢复。'; } }
function updateDefinition(value) { editorText.value = pretty(value); }
function updateField(key, value) { if (definition.value) updateDefinition({ ...definition.value, [key]: value }); }
async function inspectDraft() {
  if (!definition.value) { error('请先修正应用定义的 JSON 格式。'); return; }
  const submitted = editorText.value;
  const result = await work.mutate(api => api.preview({ definition: definition.value, ...(editor.value.appId ? { appId: editor.value.appId, baseVersionId: editor.value.baseVersionId } : {}) }));
  if (result) preview.value = { ...result, submitted };
}
async function saveDraft() {
  if (!definition.value) { error('请先修正应用定义的 JSON 格式。'); return; }
  const key = draftKey(), snapshot = readDraft(key), name = definition.value.name;
  const result = await work.save({ definition: definition.value, ...(editor.value.appId ? { appId: editor.value.appId, revision: editor.value.revision } : {}) });
  if (result) {
    clearDraftIfUnchanged(key, snapshot); editor.value = null; preview.value = null; sourceCapture.value = null;
    showValidation.value = false; showRun.value = false; savedConfirmation.value = { name, versionId: result.versionId };
    s.notice = ''; emit('captured'); await nextTick();
    savedSummary.value?.focus?.({ preventScroll: true }); savedSummary.value?.scrollIntoView?.({ block: 'start' });
  }
}
async function create(body, base = null) {
  if (props.unifiedAuthoring) {
    emit('author', { kind: 'app', intent: body.legacy ? 'upgrade' : body.sourceRunId ? 'capture' : 'create', instruction: body.instruction || (body.legacy ? '整理旧版应用，保留原业务规则，补齐实现并验证。' : ''), sourceRefs: body.sourceRunId ? [{ kind: 'sub_agent_run', reference: { runId: body.sourceRunId } }] : body.legacy ? [{ kind: 'asset_version', reference: { legacy: body.legacy } }] : [] });
    return;
  }
  const result = await work.mutate(api => api.creator(body));
  if (result) {
    if (body.sourceRunId) { sourceRunId.value = body.sourceRunId; sourceCapture.value = result; sourceStepIds.value = result.selectedStepIds || []; }
    creatorWarnings.value = [...(result.issues || []), ...(result.warnings || [])];
    if (result.selectionRequired) { editor.value = null; return; }
    openEditor(result.definition, base);
    if (body.sourceRunId) sourceBaseline.value = editorText.value;
    if (result.diff?.length) preview.value = { ...result, submitted: editorText.value, creative: true };
  }
}
function selectSourceSteps(stepIds) {
  if (editor.value && editorText.value !== sourceBaseline.value && !window.confirm('重新整理步骤会替换当前未保存草稿，是否继续？')) return;
  return create({ sourceRunId: sourceRunId.value, stepIds });
}
function cancelSource() { sourceCapture.value = null; sourceRunId.value = ''; emit('captured'); }
function returnToApps() { if (props.poolDetail) { emit('back'); return; } savedConfirmation.value = null; sourceCapture.value = null; work.close(); work.refresh(); }
async function openTests() { showValidation.value = true; showRun.value = false; await nextTick(); validationPanel.value?.scrollIntoView?.({ block: 'start' }); }
async function reviseWithCreator() {
  if (!instruction.value.trim()) return;
  if (!definition.value) { error('请先修正应用定义。'); return; }
  const context = { ...editor.value }, previous = editorText.value;
  const result = await work.mutate(api => api.creator({ definition: definition.value, instruction: instruction.value.trim() }));
  if (result) { editor.value = context; editorText.value = pretty(result.definition); creatorWarnings.value = [...(result.issues || []), ...(result.warnings || [])]; preview.value = { ...result, submitted: editorText.value, before: previous, creative: true }; instruction.value = ''; s.notice = '修改建议已写入草稿。请审阅来源与变化，再检查保存。'; }
}
async function capture() { if (props.captureRunId) { await create({ sourceRunId: props.captureRunId }); if (editor.value || sourceCapture.value) emit('captured'); } }
onMounted(capture);
watch(() => [props.initialAppId, props.initialVersionId], async ([id, versionId]) => { if (id) { await choose({ id, versionId }); if (props.initialAppId === id && s.selected?.id === id && (!versionId || s.selected.versionId === versionId)) emit('initial-opened'); } }, { immediate: true });
watch(() => props.captureRunId, value => { if (value) capture(); });
function newDraft() { if (props.embedded) { emit('join'); return; } if (props.unifiedAuthoring) { emit('author', { kind: 'app', intent: 'create' }); return; } creatorWarnings.value = []; sourceCapture.value = null; openEditor(blankDefinition(), null, true); }
function editSelected() { if (props.unifiedAuthoring) { emit('author', { kind: 'app', intent: 'edit', target: { assetId: s.selected.id, baseVersionId: s.selected.versionId, baseRevision: s.selected.revision } }); return; } creatorWarnings.value = []; openEditor(s.selected.definition, s.selected, true); }
function chooseImport() { if (props.unifiedAuthoring) emit('author', { kind: 'app', action: 'import' }); else picker.value?.click(); }
function retrySelection() { return props.poolDetail && props.initialAppId && !s.selected ? choose({ id: props.initialAppId, versionId: props.initialVersionId }) : work.refresh(); }
async function choose(item) { editor.value = null; savedConfirmation.value = null; sourceCapture.value = null; importPackage.value = null; importPreview.value = null; await work.select(item.id, item.versionId); }
async function changeVersion(event) { await work.select(s.selected.id, event.target.value); }
function startInput() {
  Object.keys(values).forEach(key => delete values[key]); Object.assign(values, inputDefaults(s.selected.definition), handoff.value?.inputs || {});
  Object.keys(fileBindings).forEach(key => delete fileBindings[key]); showRun.value = true; showValidation.value = false; s.error = '';
}
async function run() { try { const key = assetHandoffKey(props.ownerId, s.selected.id), snapshot = readDraft(key); const result = await work.run(parseRunInput(s.selected.definition, values, fileBindings)); if (result) { clearDraftIfUnchanged(key, snapshot); showRun.value = false; } } catch (cause) { error(cause.message); } }
async function verify() { try { const result = await work.verify(verificationCases(includeAdditionalCase.value ? cases.value : cases.value.slice(0, 1))); if (result) { s.notice = '验证已发起，实际结果会更新到当前版本。'; showValidation.value = false; } } catch (cause) { error(cause.message); } }
async function toggleEnable() { const result = await work.enable(!enabled.value); if (result) s.notice = enabled.value ? '此版本已启用，可以用新输入运行。' : '此版本已停用。'; }
async function inspectImport(event) {
  const file = event.target.files?.[0]; event.target.value = ''; if (!file) return;
  try {
    if (file.size > 8 * 1024 * 1024) throw new Error('应用包超过 8 MiB，请检查文件。');
    const value = parseObject(await file.text(), '应用包');
    if (value.format !== 'cd80.app-package/2') throw new Error('请选择新版完整实现包。旧研究或流程包请在旧版应用区域导入，再检查升级。');
    const result = await work.mutate(api => api.importPreview(value));
    if (result) { importPackage.value = value; importPreview.value = result; importBindings.value = {}; editor.value = null; s.notice = '已检查应用包，尚未保存或执行。'; }
  } catch (cause) { error(cause.message); }
}
async function confirmImport() { const result = await work.importApp(importPackage.value, importBindings.value); if (result) { importPackage.value = null; importPreview.value = null; s.notice = '已保存独立副本。请准备自己的连接与授权，并重新验证启用。'; } }
async function saveBindings() { const result = await work.configure(selectedBindings.value); if (result) { selectedBindings.value = clone(result.runtimeBindings || {}); s.notice = '已保存个人连接配置。原验证与启用已清除，请重新验证。'; } }
async function extract(kind) {
  if (props.unifiedAuthoring) { emit('author', { kind, intent: 'extract', instruction: '从当前应用整理独立的' + kind + '，保留原业务规则。', sourceRefs: [{ kind: 'asset_version', reference: { kind: 'app', assetId: s.selected.id, versionId: s.selected.versionId, ...(selectedNodes.value.length ? { nodeIds: [...selectedNodes.value] } : {}) } }] }); return; }
  if (!selectedNodes.value.length) { error('请先在步骤列表选择需要提取的步骤。'); return; }
  const result = await work.mutate(api => api.extract(s.selected.id, { versionId: s.selected.versionId, kind, nodeIds: [...selectedNodes.value] }));
  if (result) emit('capability-draft', { kind, ...result });
}
</script>

<template>
  <section class="asset-authoring" aria-label="统一应用工作区">
    <header v-if="!embedded && !poolDetail" class="asset-authoring-hero"><div><span class="asset-eyebrow">APPLICATIONS / 可复用的方法</span><h2>把一次成果，变成完整的方法。</h2><p>保留实际步骤、代码与资源。换输入再运行，改方法留版本。</p></div><div class="asset-actions"><button type="button" class="secondary-button" :disabled="s.busy" @click="chooseImport">导入应用原件</button><button type="button" class="primary-button" :disabled="s.busy" @click="newDraft">新建应用</button></div></header>
    <div v-if="embedded" class="asset-actions asset-pool-actions"><p>我的 Apps · 由可复用组件组成的工作流程</p><button type="button" class="secondary-button" :disabled="s.busy" @click="chooseImport">导入应用原件</button></div>
    <button v-if="poolDetail && !s.selected && !editor" type="button" class="asset-back" :disabled="s.busy" @click="returnToApps">← 我的 APP</button>
    <input ref="picker" type="file" accept=".json,application/json" hidden @change="inspectImport" />
    <div v-if="s.error" class="asset-alert error" role="alert">{{ USER_FACING_ERROR }}<button v-if="!s.busy && !editor" type="button" @click="retrySelection">重新读取状态</button></div><p v-if="s.notice" class="asset-alert notice" role="status">{{ s.notice }}</p>

    <SourceStepPicker v-if="sourceCapture?.selectionRequired" v-model="sourceStepIds" :candidates="sourceCapture.candidateSteps || []" :source="sourceCapture.source || {}" :warnings="sourceCapture.warnings || []" :busy="s.busy" @submit="selectSourceSteps" @cancel="cancelSource" />
    <section v-else-if="importPreview" class="asset-workspace" aria-label="应用包导入预览"><div class="asset-section-head"><div><span class="asset-eyebrow">IMPORT REVIEW</span><h3>核对完整实现，再保存副本</h3></div><button type="button" class="secondary-button" :disabled="s.busy" @click="importPreview = null; importPackage = null">取消</button></div><p class="asset-muted">导入不会执行。原作者的文件授权、连接秘密、验证与启用状态不会沿用。</p><div v-if="importPreview.issues?.length || importPreview.warnings?.length" class="asset-alert warning"><p>{{ USER_FACING_ERROR }}</p></div><h3>{{ importPreview.definition?.name }}</h3><AssetDefinitionView v-if="importPreview.definition" :definition="importPreview.definition" /><AssetConnectionBindings v-model="importBindings" :requirements="importPreview.bindingRequirements || []" :disabled="s.busy" @manage="emit('connections')" /><button type="button" class="primary-button" :disabled="s.busy" @click="confirmImport">导入并保存，不运行</button></section>

    <section v-else-if="editor" class="asset-workspace" aria-label="应用创作草稿">
      <div class="asset-section-head"><div><span class="asset-eyebrow">CREATOR / 创作草稿</span><h3>{{ editor.appId ? '修改当前应用，保存为新版本' : '整理你的可复用方法' }}</h3></div><button type="button" class="secondary-button" :disabled="s.busy" @click="closeEditor">收起编辑</button></div>
      <div class="asset-save-toolbar"><div><strong>先保存，测试可以稍后进行</strong><p>保存不会运行应用，也不要求填写测试输入。</p></div><button type="button" class="primary-button" :disabled="s.busy || !definition" @click="saveDraft">{{ s.busy ? '正在保存…' : '保存应用' }}</button></div>
      <details v-if="sourceCapture?.candidateSteps?.length" class="asset-source-selection"><summary>调整这次保留的步骤</summary><SourceStepPicker v-model="sourceStepIds" :candidates="sourceCapture.candidateSteps" :source="sourceCapture.source || {}" :busy="s.busy" @submit="selectSourceSteps" @cancel="sourceCapture = null" /></details>
      <form class="asset-creator-box" @submit.prevent="reviseWithCreator"><label>用自然语言描述想保留或改变的内容<textarea v-model="instruction" :disabled="s.busy" rows="3" placeholder="例如：将这次分析保存为应用，把证券和起止日期作为输入，保留计算规则与绘图代码。" /></label><div class="asset-creator-action"><small>点击后由 Creator 生成或修改草稿，会使用模型；不会执行应用。</small><button type="submit" class="secondary-button" :disabled="s.busy || !instruction.trim() || !definition">{{ s.busy ? '正在处理…' : '生成修改建议' }}</button></div></form>
      <div v-if="creatorWarnings.length" class="asset-alert warning"><p>{{ USER_FACING_ERROR }}</p></div>
      <template v-if="definition"><div class="asset-edit-fields"><label>应用名称<input :value="definition.name" :disabled="s.busy" maxlength="128" @input="updateField('name',$event.target.value)" /></label><label>用途说明<textarea :value="definition.description" :disabled="s.busy" rows="2" @input="updateField('description',$event.target.value)" /></label><label>固定规则 · 每行一条<textarea :value="(definition.rules || []).join('\n')" :disabled="s.busy" rows="3" @input="updateField('rules',$event.target.value.split('\n').filter(value => value.trim()))" /></label></div><AssetDefinitionView :definition="definition" editable :disabled="s.busy" @update:definition="updateDefinition" /></template>
      <details class="asset-advanced" :open="!definition"><summary>高级编辑 · 完整定义、输入连接与资源</summary><p>可修改参数结构、步骤顺序和输入连接。保存前会重新检查；请保留需要的完整源码与资源。</p><textarea v-model="editorText" :disabled="s.busy" rows="20" spellcheck="false" aria-label="完整应用定义" /></details><p v-if="!definition" class="asset-alert error" role="alert">{{ USER_FACING_ERROR }}</p>
      <section v-if="previewCurrent" class="asset-diff" aria-label="应用变化预览"><h3>{{ preview.creative ? 'Creator 建议的变化' : '保存前检查与变化' }}</h3><p v-if="!(preview.diff || []).length" class="asset-muted">{{ editor.appId ? '没有检测到字段变化。' : '将保存上方完整定义为一个新的应用草稿。' }}</p><details v-for="(change,index) in preview.diff || []" :key="index"><summary>{{ change.path || '完整定义' }}</summary><div class="asset-diff-columns"><div><span>修改前</span><pre>{{ pretty(change.before) ?? '未定义' }}</pre></div><div><span>修改后</span><pre>{{ pretty(change.after) ?? '已移除' }}</pre></div></div></details><div v-if="preview.issues?.length || preview.warnings?.length" class="asset-alert warning"><p>{{ USER_FACING_ERROR }}</p></div><p class="asset-muted">可保存待补草稿。仍有缺口的定义不能验证或正式运行。</p></section>
      <div class="asset-editor-footer"><button type="button" class="secondary-button" :disabled="s.busy || !definition" @click="inspectDraft">检查并预览变化</button><button type="button" class="primary-button" :disabled="s.busy || !definition" @click="saveDraft">{{ s.busy ? '正在处理…' : '确认并保存新版本' }}</button></div>
    </section>

    <section v-else-if="s.selected && !importPreview" class="asset-workspace" aria-label="统一应用详情">
      <div v-if="handoff" class="asset-alert"><strong>从应用工坊带入的问题</strong><p>{{ handoff.requirement }}</p><small>参数将在填写运行表单时带入，请检查并确认后再执行。</small></div>
      <section v-if="savedConfirmation?.versionId === s.selected.versionId" ref="savedSummary" class="asset-saved-confirmation" role="status" tabindex="-1" aria-label="应用已保存"><span aria-hidden="true">✓</span><div><h3>应用已保存</h3><p>「{{ savedConfirmation.name }}」已在我的应用中。无需现在测试，可以随时回来继续。</p><small>启用和正式运行前仍需完成验证。</small><div class="asset-actions"><button type="button" class="primary-button" @click="returnToApps">返回我的应用</button><button type="button" class="secondary-button" @click="openTests">现在测试</button></div></div></section>
      <div class="asset-section-head"><button type="button" class="asset-back" :disabled="s.busy" @click="returnToApps">{{ poolDetail ? '← 我的 APP' : '← 我的应用' }}</button><label class="asset-version">查看版本<select :value="s.selected.versionId" :disabled="s.busy || s.loading" @change="changeVersion"><option v-for="version in versions" :key="version.versionId" :value="version.versionId">{{ version.number ? 'V' + version.number : version.versionId }}{{ version.versionId === s.selected.enabledVersionId ? ' · 已启用' : '' }}</option></select></label></div>
      <div class="asset-detail-title"><div><span class="asset-state">{{ appStatus(s.selected) }}</span><h2>{{ s.selected.definition?.name || s.selected.name }}</h2><p>{{ s.selected.definition?.description || s.selected.description }}</p></div><div class="asset-actions"><button type="button" class="secondary-button" :disabled="s.busy" @click="editSelected">编辑方法</button><a class="secondary-button" :href="work.api.exportUrl(s.selected.id,s.selected.versionId)" download>导出完整实现</a></div></div>
      <div v-if="s.selected.issues?.length" class="asset-alert warning"><p>{{ USER_FACING_ERROR }}</p></div>
      <AssetDefinitionView :definition="s.selected.definition" selectable :selected-nodes="selectedNodes" :disabled="s.busy" @update:selectedNodes="selectedNodes = $event" />
      <div class="asset-extraction"><div><strong>把选中的步骤，整理成独立组件</strong><p>提取后进入新草稿审阅，不继承当前应用的验证状态。</p></div><div class="asset-actions"><button type="button" class="secondary-button" :disabled="s.busy || (!unifiedAuthoring && !selectedNodes.length)" @click="extract('tool')">提取为 Tool</button><button type="button" class="secondary-button" :disabled="s.busy || (!unifiedAuthoring && !selectedNodes.length)" @click="extract('skill')">整理为 Skill</button></div></div>
      <div v-if="s.selected.bindingRequirements?.length"><AssetConnectionBindings v-model="selectedBindings" :requirements="s.selected.bindingRequirements" :disabled="s.busy" @manage="emit('connections')" /><p class="asset-muted">修改连接后会清除当前版本的验证与启用状态。未完成的运行需要先取消。</p><button type="button" class="secondary-button" :disabled="s.busy" @click="saveBindings">保存连接配置，重新验证</button></div><section ref="validationPanel" class="asset-validation" aria-label="验证与启用"><div class="asset-section-head"><div><span class="asset-eyebrow">VERIFY / 实际验证</span><h3>{{ s.selected.verification?.status === 'passed' ? '当前版本验证通过' : !s.selected.verification?.status || s.selected.verification.status === 'unverified' ? '应用验证' : '测试与启用 · 可稍后进行' }}</h3></div><span class="asset-state">{{ ({unverified:'未验证',running:'正在验证',passed:'通过',failed:'未通过'})[s.selected.verification?.status] || '未验证' }}</span></div><AppReviewNotice :status="s.selected.verification?.status" /><p v-if="s.selected.verification?.status && s.selected.verification.status !== 'unverified'" class="asset-muted">保存已经完成。测试是单独操作，会实际执行应用；启用前至少核对原任务用例；不同输入可在下方自选。</p><div v-if="s.selected.verification?.cases?.length" class="asset-case-results"><article v-for="(item,index) in s.selected.verification.cases" :key="index"><strong>{{ item.label || '用例 ' + (index + 1) }}</strong><span>{{ runLabels[item.status] || ({passed:'通过',failed:'未通过'})[item.status] || item.status }}</span><p v-if="item.error">{{ USER_FACING_ERROR }}</p><details><summary>输入、预期与实际证据</summary><pre v-if="!item.error && item.status !== 'failed'">{{ pretty(item) }}</pre><p v-else>{{ USER_FACING_ERROR }}</p></details></article></div><div class="asset-actions"><button type="button" class="secondary-button" :disabled="s.busy || s.selected.verification?.status === 'running'" @click="showValidation = !showValidation; showRun = false">{{ showValidation ? '收起测试' : '测试此版本' }}</button><button type="button" class="primary-button" :disabled="s.busy || (!enabled && s.selected.verification?.status !== 'passed')" @click="toggleEnable">{{ enabled ? '停用此版本' : '启用此版本' }}</button><button type="button" class="primary-button" :disabled="s.busy || !enabled" @click="startInput">填写新输入运行</button></div><p v-if="!enabled" class="asset-muted">{{ s.selected.verification?.status === 'passed' ? '验证通过后仍需你主动启用。' : '当前尚未启用，不会自动运行。需要使用时再完成验证并启用。' }}</p>
        <form v-if="showValidation" class="asset-validation-form" @submit.prevent="verify">
          <p class="asset-muted">原任务用例已从当前保存版本填入；可修改。本次只提交你明确选择的用例。</p>
          <p v-if="originalNeedsCompletion" class="asset-muted" role="status">保存版本只提供了原用例候选，独立预期尚待你补全；不会凭空判定通过。</p>
          <button type="button" class="secondary-button asset-restore-case" :disabled="s.busy || !savedOriginalCase" @click="restoreOriginalCase">一键填入原用例</button>
          <fieldset :disabled="s.busy"><legend>01 · 原任务用例</legend><label>用例名称<input v-model="cases[0].label" /></label><label>本次输入（JSON）<textarea v-model="cases[0].input" rows="5" spellcheck="false" aria-label="验证输入 1" /></label><label>独立预期（JSON）<textarea v-model="cases[0].expectation" rows="5" spellcheck="false" aria-label="验证预期 1" /></label><p class="asset-muted">按最终结果字段检查：<code>{"mode":"fields","values":{"analysis.change":0.08}}</code>。请按自己的输出填写，不能用待测结果生成预期。</p><label v-for="alias in aliases" :key="alias">仅本用例授权 · {{ alias }}<select v-model="cases[0].fileBindings[alias]"><option value="">请选择文件</option><option v-for="file in files" :key="file.id" :value="file.id">{{ file.name }}</option></select></label></fieldset>
          <details class="asset-extra-case"><summary>02 · 不同输入用例（可选）</summary><button type="button" class="secondary-button" :disabled="s.busy || !savedOriginalCase" @click="copyOriginalToAdditional">从原用例填入</button><label class="asset-extra-choice"><input v-model="includeAdditionalCase" type="checkbox" :disabled="s.busy" />将这个不同输入用例加入本次验证</label><fieldset :disabled="s.busy"><label>用例名称<input v-model="cases[1].label" /></label><label>本次输入（JSON）<textarea v-model="cases[1].input" rows="5" spellcheck="false" aria-label="验证输入 2" /></label><label>独立预期（JSON）<textarea v-model="cases[1].expectation" rows="5" spellcheck="false" aria-label="验证预期 2" /></label><label v-for="alias in aliases" :key="alias">仅本用例授权 · {{ alias }}<select v-model="cases[1].fileBindings[alias]"><option value="">请选择文件</option><option v-for="file in files" :key="file.id" :value="file.id">{{ file.name }}</option></select></label></fieldset></details>
