      <section class="asset-runs-list"><div class="asset-section-head"><h3>运行记录</h3><button type="button" class="asset-back" :disabled="s.busy || s.loading" @click="work.refresh">刷新状态</button></div><p v-if="!s.runs.length" class="asset-muted">此应用还没有运行记录。</p><button v-for="item in s.runs" :key="item.id" type="button" class="asset-run-row" :class="{active:s.activeRun?.id === item.id}" :disabled="s.busy" @click="work.observeRun(item)"><span><strong>{{ item.mode === 'verification' ? '验证运行' : '正式运行' }}</strong><small>{{ item.createdAt }} · {{ item.versionId }}</small></span><span>{{ runLabels[item.status] || item.status }}</span></button><AssetAppRun v-if="s.activeRun" :key="s.activeRun.id" :run="s.activeRun" :definition="s.activeDefinition" :files="files" :busy="s.busy" @resume="work.resume(s.activeRun,$event)" @cancel="work.cancel(s.activeRun)" /></section>
